import{_ as i,a0 as r,w as o,s as d,I as n,x as t,a1 as e,A as p,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"为何你的 Python 代码应是扁平与稀疏的 | LCTT x X-CMD","titleTemplate":false,"description":"为何你的 Python 代码应是扁平与稀疏的 | LCTT (202004) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"为何你的 Python 代码应是扁平与稀疏的 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"为何你的 Python 代码应是扁平与稀疏的 | LCTT (202004) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202004/20191224 Why your Python code should be flat and sparse","title":"为何你的 Python 代码应是扁平与稀疏的","tag":"202004","desc":""},"relativePath":"202004/20191224 Why your Python code should be flat and sparse.md","filePath":"[post].md"}'),u={name:"202004/20191224 Why your Python code should be flat and sparse.md"};function h(f,s,m,b,y,g){const a=r("Link");return o(),d("div",null,[s[20]||(s[20]=n("h1",{id:"为何你的-python-代码应是扁平与稀疏的",tabindex:"-1"},[t("为何你的 Python 代码应是扁平与稀疏的 "),n("a",{class:"header-anchor",href:"#为何你的-python-代码应是扁平与稀疏的","aria-label":"Permalink to “为何你的 Python 代码应是扁平与稀疏的”"},"​")],-1)),s[21]||(s[21]=n("blockquote",null,[n("p",null,"本文是 Python 之禅特别系列的第三篇，此篇着眼于其中第五与第六条原则：扁平与稀疏。")],-1)),s[22]||(s[22]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202004/08/191645uiniiy56keig95gi.jpg",alt:""})],-1)),n("p",null,[e(a,{href:"https://www.python.org/dev/peps/pep-0020/"},{default:p(()=>[...s[0]||(s[0]=[t("Python 之禅",-1)])]),_:1}),s[1]||(s[1]=t(" 之所以得名，正是由于它那简明扼要的规则被设计出的意图在于让读者进行深入地思考，而绝不单是为编程提供一份易于遵守的指南。",-1))]),s[23]||(s[23]=l(`<p>读后不去三思其意，断然难以体会 Python 之禅的妙处。倘若 Python 之禅仅仅罗列出一组清晰的法则，那法则之间的矛盾是一种缺憾，然而作为引导读者沉思最优方案沉思的工具，矛盾却是绝佳的。</p><h3 id="扁平胜过嵌套flat-is-better-than-nested" tabindex="-1"><ruby>扁平胜过嵌套<rt>Flat is better than nested</rt></ruby> <a class="header-anchor" href="#扁平胜过嵌套flat-is-better-than-nested" aria-label="Permalink to “扁平胜过嵌套Flat is better than nested”">​</a></h3><p>迫于对缩进的强硬要求，Python 对“扁平化”的需求显然远超它者。其余编程语言为了缓解对缩进的需求，通常会在嵌套结构里加入一种“作弊”的手段。为了理解这一点，不妨一同来看看 JavaScript。</p><p>JavaScript 本质上是异步的，这意味着程序员用 JavaScript 写的代码会用到大量的回调函数。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>a(function(resultsFromA) {</span></span>
<span class="line"><span>  b(resultsFromA, function(resultsfromB) {</span></span>
<span class="line"><span>    c(resultsFromC, function(resultsFromC) {</span></span>
<span class="line"><span>      console.log(resultsFromC)</span></span>
<span class="line"><span>   }</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>忽略这段代码的具体内容，只去观察这段代码的形状与缩进带来一个最右边的点的方式。这种独特的“箭头”图形在我们扫看代码时格外扎眼，这种写法也因此被视作不可取，甚至得到了“回调地狱”的绰号。不过，在 JavaScript 中，这种反映嵌套关系的缩进可以通过“作弊”来回避。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>a(function(resultsFromA) {</span></span>
<span class="line"><span>b(resultsFromA,</span></span>
<span class="line"><span>  function(resultsfromB) {</span></span>
<span class="line"><span>c(resultsFromC,</span></span>
<span class="line"><span>  function(resultsFromC) {</span></span>
<span class="line"><span>    console.log(resultsFromC)</span></span>
<span class="line"><span>}}}</span></span></code></pre></div><p>Python 并没有提供这种作弊手段：每一级嵌套在代码中都如实的对应着一层缩进。因此，Python 深层的嵌套关系在<em>视觉</em>上也一定是深层嵌套的。这使得“回调地狱”的问题对于 Python 而言要比在 JavaScript 中严重得多：嵌套的回调函数必定带来缩进，而绝无使用花括号来“作弊”的可能。</p>`,8)),n("p",null,[s[3]||(s[3]=t("这项挑战与 Python 之禅的指导原则相结合后，在我参与的库中催生出了一个优雅的解决方案。我们在 ",-1)),e(a,{href:"https://twistedmatrix.com/trac/"},{default:p(()=>[...s[2]||(s[2]=[t("Twisted",-1)])]),_:1}),s[4]||(s[4]=t(" 框架里提出了 deferred 抽象，日后 JavaScript 中流行的 promise 抽象亦是受其启发而生。正是由于 Python 对整洁代码的坚守，方能推动 Python 开发者去发掘新的、强力的抽象。",-1))]),s[24]||(s[24]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>future_value = future_result()</span></span>
<span class="line"><span>future_value.addCallback(a)</span></span>
<span class="line"><span>future_value.addCallback(b)</span></span>
<span class="line"><span>future_value.addCallback(c)</span></span></code></pre></div><p>（现代 JavaScript 程序员也许会觉得这段代码十分眼熟：promise 着实受到了 Twisted 里 deferred 抽象的深远影响。）</p><h3 id="稀疏胜过密集sparse-is-better-than-dense" tabindex="-1"><ruby>稀疏胜过密集<rt>Sparse is better than dense</rt></ruby> <a class="header-anchor" href="#稀疏胜过密集sparse-is-better-than-dense" aria-label="Permalink to “稀疏胜过密集Sparse is better than dense”">​</a></h3><p>最易降低代码密集程度的方法是引入嵌套。这种习惯也正是有关稀疏的原则要随着前一条提出的原因：在竭尽所能地减少嵌套之后，我们往往会遗留下<em>密集的</em>代码或数据结构。此处的密集，是指塞进过量信息的小段代码，它们会导致错误发生后的解析变得困难。</p><p>这种密集性唯有通过创造性的思考方可改善，此外别无捷径。Python 之禅并不为我们提供简单的解决方案，它只会指明改善代码的方向，而非提供“如何”去做的向导。</p><p>起身走走，泡个热水澡，抑或是闻闻花香。盘坐冥思，直至灵感袭来。当你终于得到启发，便是动身写代码之时。</p><hr>`,7)),n("p",null,[s[6]||(s[6]=t("via: ",-1)),e(a,{href:"https://opensource.com/article/19/12/zen-python-flat-sparse"},{default:p(()=>[...s[5]||(s[5]=[t("https://opensource.com/article/19/12/zen-python-flat-sparse",-1)])]),_:1})]),n("p",null,[s[11]||(s[11]=t("作者：",-1)),e(a,{href:"https://opensource.com/users/moshez"},{default:p(()=>[...s[7]||(s[7]=[t("Moshe Zadka",-1)])]),_:1}),s[12]||(s[12]=t(" 选题：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[8]||(s[8]=[t("lujun9972",-1)])]),_:1}),s[13]||(s[13]=t(" 译者：",-1)),e(a,{href:"https://github.com/caiichenr"},{default:p(()=>[...s[9]||(s[9]=[t("caiichenr",-1)])]),_:1}),s[14]||(s[14]=t(" 校对：",-1)),e(a,{href:"https://github.com/wxy"},{default:p(()=>[...s[10]||(s[10]=[t("wxy",-1)])]),_:1})]),n("p",null,[s[17]||(s[17]=t("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[15]||(s[15]=[t("LCTT",-1)])]),_:1}),s[18]||(s[18]=t(" 原创编译，",-1)),e(a,{href:"https://linux.cn/"},{default:p(()=>[...s[16]||(s[16]=[t("Linux中国",-1)])]),_:1}),s[19]||(s[19]=t(" 荣誉推出",-1))])])}const T=i(u,[["render",h]]);export{P as __pageData,T as default};
